import { Json } from "./json.js";
import { FrontMatter } from "./front-matter.js";
import { Yaml } from "./yaml.js";
import { extname } from "../../deps/std.js";
export function fromFilename(path) {
    const ext = extname(path);
    switch (ext) {
        case ".json":
        case "":
            return Json;
        case ".yaml":
        case ".yml":
            return Yaml;
        default:
            return FrontMatter;
    }
}
